import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"歸妹","description":"周易集解 - 歸妹","frontmatter":{"title":"歸妹","description":"周易集解 - 歸妹"},"headers":[],"relativePath":"classics/jijie/054.md","filePath":"classics/jijie/054.md"}'),l={name:"classics/jijie/054.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="歸妹" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹" aria-label="Permalink to “歸妹”">​</a></h1><h2 id="歸妹-1" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹-1" aria-label="Permalink to “歸妹”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>歸妹，徵兇，無攸利。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：進必有所歸，故受之以歸妹。</p><p>崔憬曰：鴻漸於磐，飲食衎衎。言六比三，女漸歸夫之象也。故雲進必有所歸也。</p><p>虞翻曰：歸，嫁也。兌為妹。泰三之四，坎月離日，俱歸妹象。陰陽之義配日月，則天地交而萬物通。故以嫁娶也。</p><p>虞翻曰：謂四也。震為徵。三之四，不當位，故徵兇也。</p><p>虞翻曰：謂三也。四之三，失正無應，以柔乘剛，故無攸利也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：歸妹，天地之大義也。天地不交而萬物不興。歸妹，人之終始也。說以動，所歸妹也。徵兇，位不當也。無攸利，柔乘剛也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：乾天坤地。三之四，天地交。以離日坎月戰陰陽，陰陽之義配日月，則萬物興，故天地之大義。乾主壬，坤主癸。日月會北。震為玄黃，天地之雜。震東兌西，離南坎北。六十四卦，此象最備四時正卦，故天地之大義也。</p><p>虞翻曰：乾三之坤四。震為興。天地以離坎交陰陽，故天地不交則萬物不興矣。</p><p>王肅曰：男女交而後人民蕃，天地交然後萬物興，故歸妹以及天地交之義也。</p><p>虞翻曰：人始生乾，而終於坤，故人之終始，《雜卦》曰：歸妹，女之終，謂陰終坤癸，則乾始震庚也。</p><p>乾寶曰：歸妹者，衰落之女也。父既沒矣，兄主其禮，子續父業，人道所以相終始也。</p><p>虞翻曰：說，兌。動，震也。謂震嫁兌，所歸必妹也。</p><p>崔憬曰：中四爻皆失位，以象歸妹非正嫡，故徵兇也。</p><p>王肅曰：以徵則有不正之兇，以處則有乘剛之逆也，故無所利矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上有雷，歸妹。君子以永終知敝。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：雷薄於澤，八月九月將藏之時也。君子象之，故不敢恃當今之虞，而慮將來禍也。</p><p>虞翻曰：君子，謂乾也。坤為永終，為敝。乾為知。三之四，為永終；四之三，兌為毀折，故以永終知敝。</p><p>崔憬曰：歸妹，人之始終也。始則徵兇，終則無攸利，故君子以永終知敝為戒者也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，歸妹以娣，跛能履，徵吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：震為兄，故嫁妹。謂三也。初在三下，動而應四，故稱娣。履，禮也。初九應變成坎，坎為曳，故跛而履。應在震，為徵。初為娣。變為陰，故徵吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：歸妹以娣，以恆也。跛而履，吉相承也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陽得正，故以恆。恆動初承二，故吉相承也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，眇而視，利幽人之貞。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：視，應五也。震上兌下，離目不正，故眇而視。幽人，謂二之初動，二在坎中，故稱幽人。變得正，震喜兌說，故利幽人之貞。與履二同義也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利幽人之貞，未變常也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：常，恆也。乘初未之五，故未變常也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，歸妹以須，反歸以娣。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：須，需也。初至五，體需象，故歸妹以須。娣，謂初也。震為反，反為歸也。三失位，四反得正。兌進在四，見初進之，初在兌後，故反歸以娣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：歸妹以須，未當也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：三未變之陽，故位未當。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，歸妹愆期，遲歸有時。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：愆，過也。謂二變，三動之正，體大過象。坎月離日，為期三變。日月不見。故愆期。坎為曳，震為行，行曳，故遲也。歸謂反三。震春兌秋，坎冬離夏，四時體正，故歸有時也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：愆期之志，有待而行也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：待男行矣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：三四已正。震為帝，坤為乙，故曰帝乙。泰乾為良，為君。乾在下，為小君，則妹也。袂，口袂之飾也。兌為口，乾為衣，故稱袂。謂三失位無應。娣袂，謂二得中應五，三動成乾，為良，故｢其君之袂，不如其娣之袂良｣。故《象》曰｢以貴行也｣矣。</p><p>虞翻曰：幾，其也。坎月離日，兌西震東，日月象對，故曰幾望。二之五，四復三，得正，故吉也。與小畜、中孚月幾望同義也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：帝乙歸妹，不如其娣之袂良也。其位在中，以貴行也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：三四復正，乾為良。</p><p>虞翻曰：三四復，二之五，成既濟。五貴，故以貴行也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，女承筐無實，士刲羊無血，無攸利。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：女謂應三，兌也。自下受上稱承。震為筐。以陰應陰，三四複位，坎為虛，故無實。《象》曰｢承虛筐也｣。</p><p>虞翻曰：刲，刺也。震為士，兌為羊，離為刀，故刲羊。三四複位成泰，坎象不見，故無血。三柔乘剛，故無攸利也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：上六無實，承虛筐也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：泰坤為虛，故承虛筐也。</p>',78)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
